insert into dnew values
(1, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'ICU patients account for approximately what proportion of all hospital-acquired infections, despite occupying fewer than 10% of beds?', '[">50%", ">5%", ">20%", ">90%"]'::jsonb, 2, 'This striking disparity highlights how disproportionately vulnerable ICU patients are to hospital-acquired infection.', 'Infection Prevention'),
(2, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Barrier nursing, as classically defined, aims to:', '["Have no protective purpose", "Only apply to surgical patients", "Protect others from the patient", "Protect the patient from others"]'::jsonb, 2, 'Standard barrier nursing (source isolation) is about preventing an infected patient from spreading disease to others.', 'Infection Prevention'),
(3, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'A patient with confirmed tuberculosis requires which type of transmission-based precaution?', '["No special precautions needed", "Airborne precautions", "Droplet precautions only", "Contact precautions"]'::jsonb, 1, 'TB spreads via tiny airborne particles, requiring a negative-pressure room and fit-tested N95 respirator.', 'Infection Prevention'),
(4, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', '''Protective Environment'' precautions, used for severely immunocompromised patients, rely on:', '["No special ventilation", "Positive pressure rooms", "Negative pressure rooms", "Open-door policy"]'::jsonb, 1, 'Positive pressure keeps outside contaminated air from entering the room, protecting the vulnerable patient inside — the opposite of airborne precaution rooms.', 'Infection Prevention'),
(5, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Standard precautions differ from transmission-based precautions in that standard precautions:', '["Are only used for confirmed infections", "Replace the need for PPE entirely", "Are optional depending on staff preference", "Apply to ALL patients, all the time"]'::jsonb, 3, 'Standard precautions form the baseline of care for every patient, regardless of known infection status.', 'Infection Prevention'),
(6, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'The VAP bundle includes head-of-bed elevation of:', '["30–45 degrees", "5–10 degrees only", "Flat (0 degrees) to rest the lungs", "90 degrees at all times"]'::jsonb, 0, 'Other elements: daily sedation hold and SBT, oral care with chlorhexidine, subglottic suction, DVT and ulcer prophylaxis.', 'Infection Prevention'),
(7, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Subglottic secretion drainage reduces VAP by:', '["Replacing the need for oral care", "Sterilising the endotracheal tube lumen", "Removing pooled secretions above the tube cuff", "Increasing the cuff pressure to 60 cmH₂O"]'::jsonb, 2, 'Secretions above the cuff leak down (micro-aspiration) and cause pneumonia.', 'Infection Prevention'),
(8, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Ventilator circuits should be changed:', '["Every 6 hours routinely, by the night nurse", "Before every suction, to keep them clean", "Every day at midnight, whatever their state", "Only when visibly soiled or malfunctioning"]'::jsonb, 3, 'Frequent circuit changes increase VAP risk.', 'Infection Prevention'),
(9, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'The central line insertion bundle includes:', '["Hand hygiene, full barrier precautions, 2% chlorhexidine", "Routine antibiotic prophylaxis before insertion", "The femoral site, chosen as the preferred site", "Clean gloves and povidone-iodine skin prep only"]'::jsonb, 0, 'The subclavian site has the lowest infection risk; ultrasound guidance and a checklist are used.', 'Infection Prevention'),
(10, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Daily review of central line necessity reduces:', '["Central line-associated bloodstream infection", "Pressure injuries over the sacrum", "Ventilator-associated pneumonia in the unit", "Delirium in ventilated patients"]'::jsonb, 0, 'Remove any line that is no longer needed.', 'Infection Prevention'),
(11, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Catheter-associated urinary tract infection (CAUTI) is best prevented by:', '["Routine antibiotic prophylaxis while catheterised", "Daily bladder washouts with sterile saline", "Avoiding unneeded catheters and removing them early", "Changing the catheter every single day"]'::jsonb, 2, 'Keep a closed drainage system with the bag below bladder level.', 'Infection Prevention'),
(12, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'A patient with C. difficile diarrhoea requires:', '["No special precautions beyond standard care", "Airborne precautions with N95 masks only", "Contact precautions with soap-and-water hand washing", "Alcohol hand rub alone after each contact"]'::jsonb, 2, 'Alcohol does not kill C. difficile spores.', 'Infection Prevention'),
(13, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Reverse barrier nursing (protective isolation) is used for:', '["Severely immunocompromised patients, e.g. neutropenia", "Patients with open pulmonary tuberculosis", "Patients with C. difficile diarrhoea", "Patients colonised or infected with MRSA"]'::jsonb, 0, 'It protects the patient from others; source isolation protects others.', 'Infection Prevention'),
(14, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'The order for putting on (donning) PPE is usually:', '["Gown, mask, goggles, gloves", "Gloves, goggles, mask, gown", "Mask, gloves, gown, goggles", "Goggles, gloves, gown, mask"]'::jsonb, 0, 'Doffing is gloves, goggles, gown, mask, then hand hygiene.', 'Infection Prevention'),
(15, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Multidrug-resistant Acinetobacter in ICU spreads mainly via:', '["Contaminated hands, surfaces and equipment", "Food from the hospital kitchen", "Airborne droplets over long distances", "Mosquito bites"]'::jsonb, 0, 'Environmental cleaning and hand hygiene control outbreaks.', 'Infection Prevention'),
(16, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'A key nursing intervention to prevent line sepsis is:', '["Scrubbing the hub before every access", "Changing dressings only when they fall off", "Reusing syringes on the same patient''s line", "Leaving three-way taps open and uncapped"]'::jsonb, 0, 'Use 2% chlorhexidine in alcohol for 15 seconds.', 'Infection Prevention'),
(17, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Common causes of sepsis in critically ill patients include:', '["Only dental infections from poor oral care", "Only viral infections from visitors", "Pneumonia, line, urinary and abdominal sources", "Only skin infections from pressure ulcers"]'::jsonb, 2, 'Source identification and control are essential.', 'Infection Prevention'),
(18, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Surveillance of HAI in ICU means:', '["Counting the number of occupied beds each day", "Systematic collection and analysis of infection data", "Watching the nursing staff on CCTV cameras", "Checking the identity cards of all the visitors"]'::jsonb, 1, 'Rates guide prevention and audit.', 'Infection Prevention'),
(19, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Antimicrobial stewardship in ICU aims to:', '["Broad-spectrum antibiotics given to every ICU patient", "The right antibiotic, dose and duration, limiting resistance", "Avoiding all antibiotics, even in proven sepsis", "Giving antibiotics for viral infections to be safe"]'::jsonb, 1, 'De-escalation after culture results is key.', 'Infection Prevention'),
(20, 'Reducing Hospital-Acquired Infection in Critically Ill Patients', 'Selective digestive decontamination aims to reduce:', '["Diarrhoea caused by enteral feeds", "Gram-negative colonisation and VAP", "Hospital costs and length of stay only", "Gastric acid production and ulcers"]'::jsonb, 1, 'It uses non-absorbable antibiotics; use varies by unit.', 'Infection Prevention'),
(21, 'Emergency Procedures: Nursing Roles', 'Thoracostomy differs from thoracotomy in that it is:', '["Identical to thoracotomy", "A large incision for major intrathoracic surgery", "Only used for cardiac surgery", "A small opening for placing a chest drain"]'::jsonb, 3, 'Thoracostomy is a much smaller procedure aimed specifically at inserting a drainage tube, not full surgical access.', 'Burns & Trauma'),
(22, 'Emergency Procedures: Nursing Roles', 'Over-insertion of the guidewire during central line placement risks causing:', '["Improved cardiac function", "No clinical consequence", "Arrhythmias", "Immediate cure of the underlying condition"]'::jsonb, 2, 'If the wire is advanced too far, it can irritate the heart''s conduction system and trigger an arrhythmia.', 'Burns & Trauma'),
(23, 'Emergency Procedures: Nursing Roles', 'Before arterial line insertion, the nurse prepares a transducer set flushed with:', '["5% dextrose pressurised to 50 mmHg", "Unpressurised sterile water for injection", "Pressurised normal saline at 300 mmHg", "Heparin 25 000 units in 10 mL only"]'::jsonb, 2, 'Dextrose can cause errors in blood glucose sampling.', 'Burns & Trauma'),
(24, 'Emergency Procedures: Nursing Roles', 'An arterial line waveform that is ''over-damped'' shows:', '["A tall, spiky trace with a false high systolic", "A normal trace with a clear dicrotic notch", "An absent trace with a normal cuff pressure", "A flattened trace with a falsely low systolic"]'::jsonb, 3, 'Causes include air bubbles, clots, kinks or a soft cuff.', 'Burns & Trauma'),
(25, 'Emergency Procedures: Nursing Roles', 'The arterial transducer is levelled at the:', '["The level of the wrist where the line sits", "The sternal notch with the patient sitting up", "Phlebostatic axis (4th ICS, mid-axillary line)", "The umbilicus with the patient lying flat"]'::jsonb, 2, 'A transducer too low gives falsely high readings.', 'Burns & Trauma'),
(26, 'Emergency Procedures: Nursing Roles', 'After chest drain insertion, the nurse observes for:', '["Only the colour of the dressing at the site", "Nothing at all until the chest X-ray is done", "Swinging, bubbling, drainage volume and breathing", "Only the total volume drained at 24 hours"]'::jsonb, 2, 'Hourly drainage is recorded initially.', 'Burns & Trauma'),
(27, 'Emergency Procedures: Nursing Roles', 'A chest drain should not be clamped during transport because:', '["The drain is more likely to fall out", "It increases the risk of infection", "A tension pneumothorax may develop", "The fluid inside the tube will clot"]'::jsonb, 2, 'Keep the bottle below chest level instead.', 'Burns & Trauma'),
(28, 'Emergency Procedures: Nursing Roles', 'Underwater seal drainage works because:', '["The water seal lets air out but not back in", "Suction is always applied to the bottle", "The bottle is kept above the chest level", "The drain tube is clamped between checks"]'::jsonb, 0, 'The tube is 2–3 cm under the water.', 'Burns & Trauma'),
(29, 'Emergency Procedures: Nursing Roles', 'During pericardiocentesis, the nurse monitors:', '["Only the core temperature", "Only the capillary blood glucose", "Only the hourly urine output", "ECG for arrhythmias, with BP and SpO₂"]'::jsonb, 3, 'Ventricular puncture causes arrhythmias and bleeding.', 'Burns & Trauma'),
(30, 'Emergency Procedures: Nursing Roles', 'For diagnostic peritoneal lavage, the nurse instils:', '["50 mL of sterile water, given cold", "200 mL of X-ray contrast medium", "5 litres of 5% dextrose over one hour", "1 litre of warm saline (10 mL/kg in children)"]'::jsonb, 3, 'The fluid is drained by gravity and sent for analysis.', 'Burns & Trauma'),
(31, 'Emergency Procedures: Nursing Roles', 'A bladder scan is used in ICU to:', '["Replace the need for urine cultures", "Estimate bladder volume non-invasively", "Diagnose kidney and ureteric stones", "Measure renal blood flow and GFR"]'::jsonb, 1, 'It reduces unnecessary catheterisations.', 'Burns & Trauma'),
(32, 'Emergency Procedures: Nursing Roles', 'Before abdominal ultrasound for FAST, the patient should be:', '["In the lithotomy position", "Sitting upright at 90 degrees", "Supine, with the abdomen exposed", "Prone, with a pillow under the hips"]'::jsonb, 2, 'FAST is rapid and done during resuscitation.', 'Burns & Trauma'),
(33, 'Emergency Procedures: Nursing Roles', 'During central line insertion, the nurse''s role includes:', '["Holding the guidewire without wearing any gloves", "Ensuring the checklist is followed; stopping asepsis breaches", "Opening the packs only after the doctor has started", "Leaving the room so as not to crowd the doctor"]'::jsonb, 1, 'Nurses are empowered to stop the procedure if asepsis is broken.', 'Burns & Trauma'),
(34, 'Emergency Procedures: Nursing Roles', 'After removing a central line, the patient is asked to:', '["Take a deep breath in as the line is pulled out", "Sit upright with the legs down beside the bed", "Cough repeatedly to clear the chest during removal", "Hold the breath (Valsalva) during removal; seal the site"]'::jsonb, 3, 'This prevents air embolism.', 'Burns & Trauma'),
(35, 'Emergency Procedures: Nursing Roles', 'An intraventricular pressure monitor has the advantage that it:', '["Measures brain tissue oxygen", "Never becomes infected", "Is completely non-invasive", "Measures ICP and allows CSF drainage"]'::jsonb, 3, 'It is the gold standard for ICP measurement.', 'Burns & Trauma'),
(36, 'Emergency Procedures: Nursing Roles', 'When a chest drain accidentally falls out, the nurse should first:', '["Clamp the drain tube and replace it on the bed", "Push the drain back into the chest through the same hole", "Seal the site with a sterile occlusive dressing; call for help", "Leave the site open so that any air can escape freely"]'::jsonb, 2, 'Watch for tension pneumothorax; some advise a three-sided dressing.', 'Burns & Trauma'),
(37, 'Emergency Procedures: Nursing Roles', 'Equipment for emergency intubation in ICU should be:', '["Checked only on the day it is needed", "Checked daily, on a dedicated airway trolley", "Kept in a locked store away from the unit", "Shared with the operating theatre suite"]'::jsonb, 1, 'Include laryngoscopes, tubes, bougie, suction and capnography.', 'Burns & Trauma'),
(38, 'Emergency Procedures: Nursing Roles', 'Before a tracheostomy tube change, the nurse prepares:', '["A urinary catheter set and sterile water", "Only a new dressing and tapes for the stoma site", "Spare tubes (same and smaller), suction, oxygen, dilators", "No special equipment, as changes are routine"]'::jsonb, 2, 'The first change is usually done by the surgeon after 5–7 days.', 'Burns & Trauma'),
(39, 'Emergency Procedures: Nursing Roles', 'Emergency equipment at a tracheostomy bedside includes:', '["A defibrillator only, checked daily", "Spare tube, dilators, suction and oxygen", "A chest drain set and underwater seal", "An epidural pack and local anaesthetic"]'::jsonb, 1, 'Displacement is an airway emergency.', 'Burns & Trauma'),
(40, 'Emergency Procedures: Nursing Roles', 'Monitoring after pericardiocentesis includes observing for:', '["Hyperglycaemia and ketosis from the stress", "Re-accumulation, arrhythmias and pneumothorax", "A widespread skin rash from the antiseptic", "Diarrhoea and dehydration from the drugs"]'::jsonb, 1, 'A pericardial drain may be left in place.', 'Burns & Trauma'),
(41, 'Haemodynamic Monitoring', 'The normal CVP range is:', '["30–40mmHg", "10–20mmHg", "2–8mmHg", "0–2mmHg"]'::jsonb, 2, 'This is the accepted normal range for pressure in the central veins, reflecting venous return to the right heart.', 'Cardiovascular'),
(42, 'Haemodynamic Monitoring', 'CVP should be measured at which point in the respiratory cycle?', '["Mid-inspiration", "End of expiration", "End of inspiration", "Timing doesn''t matter"]'::jsonb, 1, 'Measuring at end-expiration minimises the effect of intrathoracic pressure changes on the reading, giving a more consistent value.', 'Cardiovascular'),
(43, 'Haemodynamic Monitoring', 'The Left Ventricular End Diastolic Volume (LVEDV) is also called:', '["Afterload", "Preload", "Cardiac Index", "Cardiac Output"]'::jsonb, 1, 'LVEDV — the volume in the ventricle just before contraction — is another name for preload.', 'Cardiovascular'),
(44, 'Haemodynamic Monitoring', 'A patient in hypovolaemic shock from acute blood loss would be expected to show which haemodynamic pattern?', '["High filling pressures with low SVR", "Low cardiac output, high SVR, low filling pressures", "Normal cardiac output with no haemodynamic change", "High cardiac output, low SVR"]'::jsonb, 1, 'Hypovolaemic shock causes low cardiac output from reduced circulating volume, compensatory vasoconstriction (high SVR), and low cardiac filling pressures.', 'Cardiovascular'),
(45, 'Haemodynamic Monitoring', 'What is the primary purpose of a Swan-Ganz catheter in critical care?', '["Monitoring blood pressure", "Measuring intracranial pressure (ICP)", "Monitoring cardiac hemodynamics", "Administering insulin"]'::jsonb, 2, 'A Swan-Ganz (pulmonary artery) catheter is used to monitor cardiac hemodynamics.', 'Cardiovascular'),
(46, 'Haemodynamic Monitoring', 'Normal pulmonary artery wedge pressure is:', '["6–12 mmHg", "0–2 mmHg", "20–30 mmHg", "40–50 mmHg"]'::jsonb, 0, 'It reflects left atrial pressure and LV preload.', 'Cardiovascular'),
(47, 'Haemodynamic Monitoring', 'Normal cardiac index is about:', '["10–12 L/min/m²", "6–8 L/min/m²", "2.5–4.0 L/min/m²", "0.5–1.0 L/min/m²"]'::jsonb, 2, 'Cardiac index adjusts output for body size.', 'Cardiovascular'),
(48, 'Haemodynamic Monitoring', 'Systemic vascular resistance is high in:', '["Cardiogenic and hypovolaemic shock", "Anaphylactic shock after a drug", "Neurogenic shock after cord injury", "Early (warm) septic shock"]'::jsonb, 0, 'Distributive shock has low SVR.', 'Cardiovascular'),
(49, 'Haemodynamic Monitoring', 'Early septic (warm) shock shows:', '["High cardiac output and low SVR", "Low wedge and high SVR", "Low cardiac output and high SVR", "Normal output and high SVR"]'::jsonb, 0, 'Late sepsis may show low output.', 'Cardiovascular'),
(50, 'Haemodynamic Monitoring', 'When floating a PA catheter, the waveform changes from RV to PA by:', '["A fall in systolic pressure towards zero", "A rise in diastolic pressure with a dicrotic notch", "A complete loss of all pulsation", "A flat trace with very large A waves"]'::jsonb, 1, 'Then the balloon wedges in a pulmonary artery branch.', 'Cardiovascular'),
(51, 'Haemodynamic Monitoring', 'The balloon of a PA catheter should be inflated:', '["With no more than 1.5 mL of air, briefly", "With 10 mL of saline for a firm wedge", "Continuously for hours to monitor PAWP", "With water to improve the wedge trace"]'::jsonb, 0, 'Prolonged wedging risks pulmonary infarction or rupture.', 'Cardiovascular'),
(52, 'Haemodynamic Monitoring', 'A permanent wedge trace on a PA catheter without balloon inflation means:', '["The balloon has burst and must be replaced", "Cardiac tamponade around the catheter", "Normal function of the catheter", "The catheter has migrated distally; pull it back"]'::jsonb, 3, 'Risk of pulmonary infarction; inform the doctor.', 'Cardiovascular'),
(53, 'Haemodynamic Monitoring', 'The thermodilution method calculates cardiac output from:', '["The temperature change of cold injectate", "The heart rate measured over one minute", "The blood pressure measured by the cuff", "The ECG voltage in the chest leads"]'::jsonb, 0, 'Several injections are averaged.', 'Cardiovascular'),
(54, 'Haemodynamic Monitoring', 'CVP is raised in:', '["Vasodilation from early septic shock", "Dehydration from vomiting and diarrhoea", "Right heart failure, fluid overload, tamponade", "Hypovolaemia from acute haemorrhage"]'::jsonb, 2, 'Trends are more useful than single values.', 'Cardiovascular'),
(55, 'Haemodynamic Monitoring', 'Mixed venous oxygen saturation (SvO₂) below 60% suggests:', '["Normal tissue oxygen extraction", "Hyperoxia from high FiO₂", "Inadequate oxygen delivery for demand", "Excess oxygen delivery to the tissues"]'::jsonb, 2, 'Normal SvO₂ is 60–80% (ScvO₂ slightly higher).', 'Cardiovascular'),
(56, 'Haemodynamic Monitoring', 'Pulse pressure variation above 13% in a ventilated patient suggests:', '["The patient is likely to be fluid responsive", "The patient is already fluid overloaded", "Cardiac tamponade is developing", "The arterial line trace is damped"]'::jsonb, 0, 'It is valid only in sinus rhythm with controlled ventilation.', 'Cardiovascular'),
(57, 'Haemodynamic Monitoring', 'A passive leg raise test assesses:', '["Spinal reflexes after cord injury", "The risk of deep vein thrombosis", "Leg circulation in arterial disease", "Fluid responsiveness without giving fluid"]'::jsonb, 3, 'A rise in cardiac output of 10% or more suggests responsiveness.', 'Cardiovascular'),
(58, 'Haemodynamic Monitoring', 'Inotropes increase:', '["Venous capacity", "Systemic vascular resistance only", "Myocardial contractility", "Heart block"]'::jsonb, 2, 'Examples: dobutamine, milrinone, adrenaline.', 'Cardiovascular'),
(59, 'Haemodynamic Monitoring', 'Vasopressors mainly increase:', '["SVR and blood pressure", "Contractility only", "Venous capacity", "Heart block"]'::jsonb, 0, 'Noradrenaline is first-line in septic shock.', 'Cardiovascular'),
(60, 'Haemodynamic Monitoring', 'The intra-aortic balloon pump inflates during:', '["Only during cardiac arrest", "Systole, increasing the afterload", "Diastole, improving coronary flow", "Both phases equally throughout"]'::jsonb, 2, 'It deflates just before systole to reduce afterload.', 'Cardiovascular'),
(61, 'Mechanical Ventilation, ARDS and Weaning', 'PEEP settings in ventilated life-threatening asthma should be:', '["Equal to peak inspiratory pressure", "Minimal (<5cmH2O)", "Zero at all times", "High (>15cmH2O)"]'::jsonb, 1, 'Because intrinsic PEEP is already present from trapped air, adding a lot more external PEEP worsens the trapping.', 'Respiratory'),
(62, 'Mechanical Ventilation, ARDS and Weaning', 'The negative inspiratory force required for weaning readiness is at least:', '["-100cmH2O", "-20cmH2O", "-5cmH2O", "Not relevant to weaning"]'::jsonb, 1, 'This measure of inspiratory muscle strength needs to reach at least this level to suggest adequate strength for weaning.', 'Respiratory'),
(63, 'Mechanical Ventilation, ARDS and Weaning', 'An FiO₂ below what value is generally required before considering weaning?', '["<0.5", "<0.8", "FiO₂ is irrelevant to weaning", "<0.2"]'::jsonb, 0, 'Needing a lower oxygen concentration suggests the lungs are functioning well enough to attempt weaning.', 'Respiratory'),
(64, 'Mechanical Ventilation, ARDS and Weaning', 'One of the following is a risk of keeping high PEEP', '["Hypothermia", "Hypertension", "Hypotension", "Hyperthermia"]'::jsonb, 2, 'High PEEP raises intrathoracic pressure, reducing venous return and risking hypotension.', 'Respiratory'),
(65, 'Mechanical Ventilation, ARDS and Weaning', 'Lung-protective ventilation in ARDS uses a tidal volume of:', '["12 mL/kg of actual body weight", "6 mL/kg of predicted body weight", "15 mL/kg of predicted weight", "3 mL/kg of actual weight"]'::jsonb, 1, 'Plateau pressure is kept at or below 30 cmH₂O.', 'Respiratory'),
(66, 'Mechanical Ventilation, ARDS and Weaning', 'Plateau pressure is measured by:', '["An expiratory hold at end-expiration", "Reading the peak airway pressure", "Disconnecting the patient briefly", "An inspiratory hold at end-inspiration"]'::jsonb, 3, 'It reflects alveolar pressure and lung compliance.', 'Respiratory'),
(67, 'Mechanical Ventilation, ARDS and Weaning', 'Prone positioning in severe ARDS improves:', '["Sedation needs, by improving comfort", "Renal function, by better perfusion", "Oxygenation through better V/Q matching", "Cardiac output, by direct compression"]'::jsonb, 2, 'It is used for at least 16 hours a day when P/F ratio is below 150.', 'Respiratory'),
(68, 'Mechanical Ventilation, ARDS and Weaning', 'A P/F ratio of 90 mmHg on PEEP 10 indicates:', '["Mild ARDS", "Normal lung function", "Moderate ARDS", "Severe ARDS"]'::jsonb, 3, 'Berlin: mild 200–300, moderate 100–200, severe 100 or less.', 'Respiratory'),
(69, 'Mechanical Ventilation, ARDS and Weaning', 'Pressure support ventilation means:', '["No breaths are delivered unless the patient is apnoeic", "Each spontaneous breath is supported by a set pressure", "All breaths are mandatory at a set rate and volume", "A fixed tidal volume is forced in with each breath"]'::jsonb, 1, 'It is often used for weaning.', 'Respiratory'),
(70, 'Mechanical Ventilation, ARDS and Weaning', 'A spontaneous breathing trial is considered failed if:', '["RR over 35, SpO₂ under 90%, rising HR and distress", "SpO₂ is 96% on 40% oxygen with good air entry", "The patient is calm with a respiratory rate of 18", "The patient obeys commands and coughs well"]'::jsonb, 0, 'Failure returns the patient to full support.', 'Respiratory'),
(71, 'Mechanical Ventilation, ARDS and Weaning', 'The rapid shallow breathing index (RR/VT in litres) predicting weaning success is below:', '["20", "500", "300", "105"]'::jsonb, 3, 'Higher values suggest weaning failure.', 'Respiratory'),
(72, 'Mechanical Ventilation, ARDS and Weaning', 'Auto-PEEP is most likely in:', '["Normal lungs after elective surgery", "ARDS ventilated at a low rate", "Asthma or COPD with short expiratory time", "Pulmonary fibrosis with stiff lungs"]'::jsonb, 2, 'Increase expiratory time by reducing rate or I:E ratio.', 'Respiratory'),
(73, 'Mechanical Ventilation, ARDS and Weaning', 'High peak pressure with normal plateau pressure suggests:', '["Reduced lung compliance, as in ARDS or oedema", "A large pneumothorax on the ventilated side", "Increased airway resistance (secretions, bronchospasm)", "Normal lungs with a normal airway"]'::jsonb, 2, 'High plateau pressure suggests low compliance.', 'Respiratory'),
(74, 'Mechanical Ventilation, ARDS and Weaning', 'Volutrauma refers to lung injury from:', '["Infection of the lower airways", "Over-distension by large tidal volumes", "Low PEEP causing alveolar collapse", "Oxygen toxicity from high FiO₂"]'::jsonb, 1, 'Atelectrauma comes from repeated opening and closing of alveoli.', 'Respiratory'),
(75, 'Mechanical Ventilation, ARDS and Weaning', 'A sudden fall in SpO₂ with absent breath sounds on the left after intubation suggests:', '["Right main bronchus intubation", "A left-sided pneumothorax in every case", "Severe bronchospasm on both sides", "A massive pulmonary embolism"]'::jsonb, 0, 'Withdraw the tube a few centimetres and recheck.', 'Respiratory'),
(76, 'Mechanical Ventilation, ARDS and Weaning', 'Non-invasive ventilation is contraindicated in:', '["Inability to protect the airway, or vomiting", "COPD with hypercapnic respiratory failure", "Acute cardiogenic pulmonary oedema", "Obesity hypoventilation syndrome"]'::jsonb, 0, 'Facial trauma and recent upper GI surgery are other contraindications.', 'Respiratory'),
(77, 'Mechanical Ventilation, ARDS and Weaning', 'High-flow nasal oxygen provides:', '["Heated, humidified oxygen with a small PEEP effect", "Full mechanical ventilation without a tube", "Negative pressure ventilation of the chest", "Only low-flow dry oxygen through the nose"]'::jsonb, 0, 'Flows of 30–60 L/min are used.', 'Respiratory'),
(78, 'Mechanical Ventilation, ARDS and Weaning', 'A ventilated patient''s tidal volume falls with low pressure alarms. The nurse checks first for:', '["A circuit disconnection or cuff leak", "Coughing against the ventilator", "Severe bronchospasm", "A blocked endotracheal tube"]'::jsonb, 0, 'Low pressure means air is escaping.', 'Respiratory'),
(79, 'Mechanical Ventilation, ARDS and Weaning', 'Daily sedation interruption mainly helps to:', '["Reduce ventilation time and ICU stay", "Increase the rate of delirium", "Increase the rate of VAP", "Prolong the time to weaning"]'::jsonb, 0, 'It is combined with spontaneous breathing trials.', 'Respiratory'),
(80, 'Mechanical Ventilation, ARDS and Weaning', 'A cuff leak test before extubation assesses:', '["Cardiac output", "Laryngeal oedema risk", "Lung compliance", "Gas exchange in lungs"]'::jsonb, 1, 'Absent leak suggests risk of post-extubation stridor.', 'Respiratory'),
(81, 'Renal, Fluids, Electrolytes and Acid–Base', 'In peritoneal dialysis, the dialysate is', '["Normosmolar", "Hyposmolar", "Hyperosmosis", "Hyperosmolar"]'::jsonb, 3, 'Peritoneal dialysate is hyperosmolar to draw fluid/waste out of the blood by osmosis.', 'Renal & Fluid Balance'),
(82, 'Renal, Fluids, Electrolytes and Acid–Base', 'A 53-year-old patient who is receiving ibuprofen 400 mg twice a day, for chronic, low back pain develops lower-extremity oedema. The pain management nurse suspects that the oedema is caused by:', '["An increase in glomerular filtration rate", "A decrease in renal function", "A low creatinine level.", "An increase in plasma proteins."]'::jsonb, 1, 'NSAIDs can reduce renal blood flow/function, causing fluid retention and oedema.', 'Renal & Fluid Balance'),
(83, 'Renal, Fluids, Electrolytes and Acid–Base', 'KDIGO stage 3 acute kidney injury includes urine output below:', '["Under 0.5 mL/kg/h for 6 consecutive hours", "Under 2 mL/kg/h for 1 hour after surgery", "Under 0.3 mL/kg/h for 24 h, or anuria for 12 h", "Under 1 mL/kg/h for 2 consecutive hours"]'::jsonb, 2, 'Creatinine three times baseline also defines stage 3.', 'Renal & Fluid Balance'),
(84, 'Renal, Fluids, Electrolytes and Acid–Base', 'A urinary sodium below 20 mmol/L in oliguria suggests:', '["Established acute tubular necrosis", "Recent loop diuretic administration", "Post-renal obstruction of the outflow", "Pre-renal AKI with intact tubules"]'::jsonb, 3, 'ATN causes urinary sodium above 40 mmol/L.', 'Renal & Fluid Balance'),
(85, 'Renal, Fluids, Electrolytes and Acid–Base', 'Indications for urgent dialysis include:', '["Hypokalaemia from diuretic therapy", "A creatinine of 120 µmol/L with good output", "Mild oliguria for 2 hours after surgery", "Refractory high K⁺, acidosis, overload, uraemia"]'::jsonb, 3, 'Remember AEIOU: acidosis, electrolytes, intoxication, overload, uraemia.', 'Renal & Fluid Balance'),
(86, 'Renal, Fluids, Electrolytes and Acid–Base', 'CRRT is preferred to intermittent haemodialysis in:', '["Haemodynamically unstable patients", "Patients who can walk", "Stable outpatients", "Patients with no kidney disease"]'::jsonb, 0, 'Slow continuous removal avoids hypotension.', 'Renal & Fluid Balance'),
(87, 'Renal, Fluids, Electrolytes and Acid–Base', 'Citrate anticoagulation in CRRT requires monitoring of:', '["Ionised calcium in the patient and circuit", "The blood glucose only, every 4 hours", "The platelet count only, checked daily", "The urine sodium only, every 12 hours"]'::jsonb, 0, 'Calcium is replaced by infusion.', 'Renal & Fluid Balance'),
(88, 'Renal, Fluids, Electrolytes and Acid–Base', 'ABG: pH 7.20, PaCO₂ 25 mmHg, HCO₃⁻ 10 mmol/L indicates:', '["Mixed respiratory and metabolic alkalosis", "Metabolic alkalosis with respiratory compensation", "Acute respiratory acidosis without compensation", "Metabolic acidosis with respiratory compensation"]'::jsonb, 3, 'Expected PaCO₂ = 1.5 × HCO₃⁻ + 8 (±2) = 23 mmHg.', 'Renal & Fluid Balance'),
(89, 'Renal, Fluids, Electrolytes and Acid–Base', 'ABG: pH 7.48, PaCO₂ 48 mmHg, HCO₃⁻ 35 mmol/L indicates:', '["Metabolic acidosis with respiratory compensation", "Metabolic alkalosis with respiratory compensation", "Respiratory acidosis with metabolic compensation", "Acute respiratory alkalosis from hyperventilation"]'::jsonb, 1, 'Causes include vomiting, NG suction and diuretics.', 'Renal & Fluid Balance'),
(90, 'Renal, Fluids, Electrolytes and Acid–Base', 'A normal anion gap metabolic acidosis is caused by:', '["Diarrhoea or large volumes of 0.9% saline", "Methanol poisoning with visual loss", "Diabetic ketoacidosis with high ketones", "Lactic acidosis from septic shock"]'::jsonb, 0, 'Hyperchloraemic acidosis follows saline infusion.', 'Renal & Fluid Balance'),
(91, 'Renal, Fluids, Electrolytes and Acid–Base', 'Hypokalaemia on the ECG shows:', '["Flat T waves and prominent U waves", "ST elevation in all of the leads", "Tall, peaked T waves in V2–V4", "Wide QRS complexes and sine waves"]'::jsonb, 0, 'It increases digoxin toxicity and arrhythmias.', 'Renal & Fluid Balance'),
(92, 'Renal, Fluids, Electrolytes and Acid–Base', 'IV potassium on a general ICU line should usually not exceed:', '["50 mmol given over 5 minutes in an arrest", "An undiluted bolus through any IV line", "100 mmol/hour through a peripheral cannula", "10–20 mmol/hour via a central line with monitoring"]'::jsonb, 3, 'Concentrated potassium is a high-alert drug.', 'Renal & Fluid Balance'),
(93, 'Renal, Fluids, Electrolytes and Acid–Base', 'Hypomagnesaemia may cause:', '["Hypertension only, with headache", "Bradycardia only, with heart block", "Torsades and refractory hypokalaemia", "Polyuria only, with thirst"]'::jsonb, 2, 'Magnesium is replaced before potassium will correct.', 'Renal & Fluid Balance'),
(94, 'Renal, Fluids, Electrolytes and Acid–Base', 'Hypophosphataemia in ICU may cause:', '["Hypercalcaemia with kidney stones and polyuria", "Respiratory muscle weakness and failed weaning", "Tetany only, without any muscle weakness", "Severe hypertension with headache and blurring"]'::jsonb, 1, 'Common in refeeding and DKA treatment.', 'Renal & Fluid Balance'),
(95, 'Renal, Fluids, Electrolytes and Acid–Base', 'Fluid balance charts are most useful when:', '["Left blank during the night shift", "Estimated without any measurement", "Filled in once a week by the manager", "Totalled every 24 hours, with daily weights"]'::jsonb, 3, 'Cumulative positive balance worsens outcomes.', 'Renal & Fluid Balance'),
(96, 'Renal, Fluids, Electrolytes and Acid–Base', 'Over-hydration (fluid overload) is suggested by:', '["Low JVP with tachycardia and cool hands", "Weight loss with a dry mouth and thirst", "Weight gain, raised JVP, crackles, oedema", "Concentrated dark urine with high urea"]'::jsonb, 2, 'Diuretics or ultrafiltration may be needed.', 'Renal & Fluid Balance'),
(97, 'Renal, Fluids, Electrolytes and Acid–Base', 'Dehydration is suggested by:', '["Polyuria with very dilute urine and low urea", "Bradycardia with peripheral oedema and weight gain", "Raised JVP with basal crackles and a gallop", "Tachycardia, dry mucosa, oliguria, raised urea"]'::jsonb, 3, 'Urea rises more than creatinine in pre-renal states.', 'Renal & Fluid Balance'),
(98, 'Renal, Fluids, Electrolytes and Acid–Base', 'The kidneys compensate for respiratory acidosis by:', '["Retaining bicarbonate and excreting H⁺", "Retaining hydrogen ions in the blood", "Excreting bicarbonate in the urine", "Increasing the rate of breathing"]'::jsonb, 0, 'Compensation takes 3–5 days.', 'Renal & Fluid Balance'),
(99, 'Renal, Fluids, Electrolytes and Acid–Base', 'The lungs compensate for metabolic acidosis by:', '["Hypoventilation to raise PaCO₂", "Retaining bicarbonate", "Hyperventilation to lower PaCO₂", "Excreting ammonium"]'::jsonb, 2, 'Kussmaul breathing in DKA is an example.', 'Renal & Fluid Balance'),
(100, 'Renal, Fluids, Electrolytes and Acid–Base', 'Nephrotoxic drugs to avoid in AKI include:', '["Insulin given by continuous infusion", "Aminoglycosides, NSAIDs, IV contrast", "Oxygen given by face mask or cannula", "Paracetamol in normal therapeutic doses"]'::jsonb, 1, 'Doses of renally cleared drugs are adjusted.', 'Renal & Fluid Balance'),
(101, 'Laboratory Sciences: Haematology and Transfusion', 'Coagulopathy or low platelet count in a patient with GI bleeding:', '["Increases the risk of rebleeding", "Has no bearing on bleeding risk", "Reduces the risk of rebleeding", "Only matters in upper GI bleeds, not lower"]'::jsonb, 0, 'If the blood can''t clot effectively, any bleeding point is far more likely to continue or restart.', 'Laboratory Sciences & Haematology'),
(102, 'Laboratory Sciences: Haematology and Transfusion', 'A client is receiving a blood transfusion. The critical care nurse observes that the client is experiencing diarrhoea, abdominal pain, and chills. Which of the following actions should the nurse take FIRST?', '["Administer meperidine.", "Stop the transfusion.", "Assist the client to the bathroom.", "Get a warming blanket."]'::jsonb, 1, 'Diarrhoea, pain, and chills during a transfusion signal a reaction — stopping the transfusion is the first priority action.', 'Laboratory Sciences & Haematology'),
(103, 'Laboratory Sciences: Haematology and Transfusion', 'Percussion as an airway clearance technique is contraindicated in a patient with:', '["Cystic fibrosis", "Platelet count <20,000", "Post-operative atelectasis", "Retained secretions"]'::jsonb, 1, 'Very low platelets increase the risk of bruising or bleeding from the repeated impact of percussion.', 'Laboratory Sciences & Haematology'),
(104, 'Laboratory Sciences: Haematology and Transfusion', 'A febrile non-haemolytic transfusion reaction is managed by:', '["Ignore it and continue at the same rate", "Speed up the transfusion to finish it", "Slow or stop the transfusion; give paracetamol", "Give IV potassium to correct the fever"]'::jsonb, 2, 'Exclude haemolysis and bacterial contamination.', 'Laboratory Sciences & Haematology'),
(105, 'Laboratory Sciences: Haematology and Transfusion', 'Transfusion-related acute lung injury (TRALI) presents within 6 hours with:', '["Hypertension with a raised JVP and oedema", "Hyperkalaemia only, with peaked T waves", "Hypoxia and bilateral infiltrates, no fluid overload", "A localised rash only, with normal oxygen"]'::jsonb, 2, 'TACO, in contrast, has fluid overload and raised JVP.', 'Laboratory Sciences & Haematology'),
(106, 'Laboratory Sciences: Haematology and Transfusion', 'Transfusion-associated circulatory overload (TACO) is treated with:', '["Give more blood quickly to finish", "Stop, sit up, give oxygen and diuretics", "Start broad-spectrum antibiotics", "Lie the patient completely flat"]'::jsonb, 1, 'Elderly and cardiac patients are at higher risk.', 'Laboratory Sciences & Haematology'),
(107, 'Laboratory Sciences: Haematology and Transfusion', 'Each unit of blood should be completed within:', '["24 hours of leaving the fridge", "4 hours of leaving the fridge", "12 hours of leaving the fridge", "30 minutes of leaving the fridge"]'::jsonb, 1, 'Longer times increase bacterial growth.', 'Laboratory Sciences & Haematology'),
(108, 'Laboratory Sciences: Haematology and Transfusion', 'Platelets should not be given through:', '["A central line", "A platelet or new standard giving set", "A peripheral cannula", "A used blood giving set"]'::jsonb, 3, 'Use a fresh set to avoid platelet loss.', 'Laboratory Sciences & Haematology'),
(109, 'Laboratory Sciences: Haematology and Transfusion', 'DIC laboratory findings include:', '["Normal clotting times with a low D-dimer level", "High platelets and high fibrinogen with short clotting times", "Isolated high haemoglobin with normal platelets", "Low platelets and fibrinogen, long PT/APTT, high D-dimer"]'::jsonb, 3, 'Treat the cause and replace components.', 'Laboratory Sciences & Haematology'),
(110, 'Laboratory Sciences: Haematology and Transfusion', 'Heparin-induced thrombocytopenia (HIT) typically occurs:', '["Only after switching to oral warfarin", "Within minutes of the first heparin dose", "Only with LMWH given to young children", "5–10 days after starting heparin, with thrombosis"]'::jsonb, 3, 'Stop all heparin and use an alternative anticoagulant.', 'Laboratory Sciences & Haematology'),
(111, 'Laboratory Sciences: Haematology and Transfusion', 'A sickle cell crisis transfusion target is usually HbS below:', '["70%", "50%", "90%", "30%"]'::jsonb, 3, 'Exchange transfusion lowers HbS rapidly in severe crises.', 'Laboratory Sciences & Haematology'),
(112, 'Laboratory Sciences: Haematology and Transfusion', 'A low reticulocyte count in anaemia indicates:', '["Acute bleeding with good marrow", "Increased red cell destruction", "Haemolysis", "Reduced bone marrow production"]'::jsonb, 3, 'High reticulocytes suggest haemolysis or bleeding.', 'Laboratory Sciences & Haematology'),
(113, 'Laboratory Sciences: Haematology and Transfusion', 'A blood film showing fragmented red cells (schistocytes) suggests:', '["Microangiopathic haemolysis (DIC, TTP)", "Vitamin B12 deficiency with large cells", "Iron deficiency from chronic bleeding", "A normal blood film in a healthy adult"]'::jsonb, 0, 'TTP needs urgent plasma exchange.', 'Laboratory Sciences & Haematology'),
(114, 'Laboratory Sciences: Haematology and Transfusion', 'The commonest pathogens in Nigerian ICUs include:', '["Only respiratory viruses such as influenza", "Only fungi such as Candida and Aspergillus", "Klebsiella, Pseudomonas, S. aureus, Acinetobacter", "Only parasites such as malaria and worms"]'::jsonb, 2, 'Resistance is common; culture and sensitivity guide therapy.', 'Laboratory Sciences & Haematology'),
(115, 'Laboratory Sciences: Haematology and Transfusion', 'Blood cultures should be taken:', '["Before antibiotics, from two sites, aseptically", "Without skin preparation, to save time", "After antibiotics, from a single site only", "From the arterial line only, after flushing"]'::jsonb, 0, 'At least 10 mL per bottle in adults.', 'Laboratory Sciences & Haematology'),
(116, 'Laboratory Sciences: Haematology and Transfusion', 'Culture and sensitivity results guide:', '["Sedation dosing in ventilated patients", "Antibiotic choice and de-escalation", "Blood group selection for transfusion", "The choice of IV maintenance fluid"]'::jsonb, 1, 'Empirical therapy is changed once results return.', 'Laboratory Sciences & Haematology'),
(117, 'Laboratory Sciences: Haematology and Transfusion', 'Albumin is low in critical illness mainly because of:', '["Overfeeding with enteral feeds", "Excess dietary intake", "Dehydration and diuretics", "Inflammation and capillary leak"]'::jsonb, 3, 'Albumin is a poor nutritional marker in ICU.', 'Laboratory Sciences & Haematology'),
(118, 'Laboratory Sciences: Haematology and Transfusion', 'Raised serum lactate after cardiac arrest mainly reflects:', '["Hyperventilation by the team during CPR", "Excess dietary lactate given in the enteral feed", "Liver overproduction of glucose after adrenaline", "Tissue hypoperfusion and anaerobic metabolism"]'::jsonb, 3, 'Clearance of lactate suggests improving perfusion.', 'Laboratory Sciences & Haematology'),
(119, 'Laboratory Sciences: Haematology and Transfusion', 'The modified Allen''s test is positive (normal) when:', '["The hand stays pale for more than 30 seconds", "The patient feels pain in the fingers", "Colour returns within 5–15 seconds after ulnar release", "The radial pulse disappears on release"]'::jsonb, 2, 'A delayed return suggests poor ulnar collateral flow.', 'Laboratory Sciences & Haematology'),
(120, 'Laboratory Sciences: Haematology and Transfusion', 'Protein-calorie malnutrition in ICU leads to:', '["Poor healing, infection and weak breathing muscles", "Faster recovery from the critical illness", "Better immunity against hospital infections", "Weight gain only, with no harmful effects"]'::jsonb, 0, 'Early nutrition reduces complications.', 'Laboratory Sciences & Haematology'),
(121, 'Radiology in the Critically Ill', 'In a tension pneumothorax on X-ray, the trachea deviates to the:', '["Same (ipsilateral) side", "Opposite (contralateral) side", "Remains exactly midline", "Cannot be assessed on X-ray"]'::jsonb, 1, 'Trapped air under pressure pushes the mediastinal structures, including the trachea, away from the affected side.', 'Radiology & Imaging'),
(122, 'Radiology in the Critically Ill', 'Patient had head trauma and you suspect that he has intracranial haemorrhage, Which of following modalities you will choose?', '["CT", "Conventional x-ray", "MRI", "X-ray with contrast"]'::jsonb, 0, 'CT is the imaging modality of choice for detecting acute intracranial haemorrhage.', 'Radiology & Imaging'),
(123, 'Radiology in the Critically Ill', 'On a chest X-ray, the tip of a central venous catheter should lie in the:', '["High in the internal jugular vein", "Inside the right ventricle cavity", "In the left subclavian vein", "Lower SVC, just above the right atrium"]'::jsonb, 3, 'A tip in the atrium may cause arrhythmias or perforation.', 'Radiology & Imaging'),
(124, 'Radiology in the Critically Ill', 'A nasogastric tube on chest X-ray is correctly placed when it:', '["Down the midline, below the diaphragm on the left", "Coiled in the pharynx behind the tongue", "Ending above the clavicle in the neck", "Following the line of the right main bronchus"]'::jsonb, 0, 'A tube in the bronchus must be removed before feeding.', 'Radiology & Imaging'),
(125, 'Radiology in the Critically Ill', 'Air bronchograms on chest X-ray indicate:', '["A pneumothorax with collapse of the lung", "A pleural effusion at the lung base", "Air-filled bronchi within consolidated lung", "Normal lung with clear, aerated air spaces"]'::jsonb, 2, 'Seen in pneumonia and ARDS.', 'Radiology & Imaging'),
(126, 'Radiology in the Critically Ill', 'Bat-wing perihilar shadowing with Kerley B lines suggests:', '["Right lower lobe pneumonia", "Tension pneumothorax", "Cardiogenic pulmonary oedema", "Massive pulmonary embolism"]'::jsonb, 2, 'Upper lobe venous diversion and effusions may also be seen.', 'Radiology & Imaging'),
(127, 'Radiology in the Critically Ill', 'A haemothorax on an erect chest X-ray shows:', '["Hyperinflation with flat diaphragms", "A meniscus opacity blunting the costophrenic angle", "A visible lung edge with no markings beyond it", "Free air under the right hemidiaphragm"]'::jsonb, 1, 'Haemopneumothorax shows a flat air-fluid level.', 'Radiology & Imaging'),
(128, 'Radiology in the Critically Ill', 'A pneumothorax on chest X-ray shows:', '["White-out of the whole of one lung", "A pleural line with no lung markings beyond", "Kerley B lines at both lung bases", "Air bronchograms within a lobe"]'::jsonb, 1, 'Tension pneumothorax adds mediastinal shift.', 'Radiology & Imaging'),
(129, 'Radiology in the Critically Ill', 'Dilated small bowel loops with multiple air-fluid levels suggest:', '["Small bowel obstruction", "A normal gas pattern", "Gross ascites", "Perforation only"]'::jsonb, 0, 'Valvulae conniventes cross the whole small bowel width.', 'Radiology & Imaging'),
(130, 'Radiology in the Critically Ill', 'Free air under the diaphragm on erect chest X-ray suggests:', '["Right lower lobe pneumonia", "Perforated hollow viscus", "Amoebic liver abscess", "Right-sided pleural effusion"]'::jsonb, 1, 'Recent laparotomy can also cause free air.', 'Radiology & Imaging'),
(131, 'Radiology in the Critically Ill', 'Before IV contrast, the nurse checks:', '["Hearing and the use of hearing aids", "Renal function, allergy history, metformin use", "Visual acuity and the use of spectacles", "Hair colour and the use of hair dye"]'::jsonb, 1, 'Hydration reduces contrast nephropathy.', 'Radiology & Imaging'),
(132, 'Radiology in the Critically Ill', 'An intravenous urogram (IVU/IVP) shows:', '["Kidneys, ureters and bladder after contrast", "The lungs and the pleural spaces", "The brain ventricles and basal cisterns", "The heart chambers and the heart valves"]'::jsonb, 0, 'It is largely replaced by CT urography.', 'Radiology & Imaging'),
(133, 'Radiology in the Critically Ill', 'A CVP line check X-ray is also used to exclude:', '["An acute ischaemic stroke", "Pneumothorax after insertion", "Acute appendicitis", "A fractured femoral neck"]'::jsonb, 1, 'Especially after subclavian or jugular insertion.', 'Radiology & Imaging'),
(134, 'Radiology in the Critically Ill', 'Radiation protection for the ICU nurse during portable X-ray includes:', '["Taking no precautions for portable films", "Standing directly behind the X-ray tube", "Standing 2 metres away or wearing a lead apron", "Holding the patient still within the beam"]'::jsonb, 2, 'Time, distance and shielding reduce exposure.', 'Radiology & Imaging'),
(135, 'Radiology in the Critically Ill', 'An endotracheal tube on X-ray should be:', '["In the right bronchus", "Below the carina", "3–5 cm above the carina", "At the vocal cords"]'::jsonb, 2, 'Head flexion moves the tube down; extension moves it up.', 'Radiology & Imaging'),
(136, 'Radiology in the Critically Ill', 'A ''white-out'' of one hemithorax with mediastinal shift away suggests:', '["Tension pneumothorax", "A large pleural effusion", "Lobar collapse", "Previous pneumonectomy"]'::jsonb, 1, 'Collapse pulls the mediastinum towards the lesion.', 'Radiology & Imaging'),
(137, 'Radiology in the Critically Ill', 'CT scanning is preferred over plain X-ray in head injury because it shows:', '["Intracranial bleeding and swelling", "Only wounds of the scalp", "Only disease of the sinuses", "Only fractures of the skull"]'::jsonb, 0, 'Non-contrast CT is the first investigation.', 'Radiology & Imaging'),
(138, 'Radiology in the Critically Ill', 'When transferring a ventilated patient for CT, the nurse should:', '["Stop all infusions until the patient returns", "Portable monitoring, oxygen, suction and emergency drugs", "Disconnect all monitoring to make the transfer faster", "Send the patient without a nurse to save staff"]'::jsonb, 1, 'Transfers are high-risk periods.', 'Radiology & Imaging'),
(139, 'Radiology in the Critically Ill', 'Ultrasound is useful in ICU to:', '["Guide line insertion; assess fluid, lungs, heart", "Measure the ICP directly at the bedside", "Replace every CT scan in the ICU", "Diagnose all fractures in trauma patients"]'::jsonb, 0, 'Point-of-care ultrasound is widely used.', 'Radiology & Imaging'),
(140, 'Radiology in the Critically Ill', 'Pneumoperitoneum after laparoscopy usually:', '["Never occurs", "Resolves within a few days", "Always means perforation", "Requires surgery"]'::jsonb, 1, 'Clinical correlation is required.', 'Radiology & Imaging'),
(141, 'Nutrition and Physiotherapy in Critical Care', 'Which of the following macronutrients in parenteral nutrition may need to be increased in a patient who has large, nonhealing wounds?', '["Trace elements", "Lipids", "Protein", "Carbohydrates"]'::jsonb, 2, 'Protein needs rise substantially with large non-healing wounds to support tissue repair.', 'Mixed Revision'),
(142, 'Nutrition and Physiotherapy in Critical Care', 'A patient''s enteral feed provides 60 g carbohydrate, 20 g protein, and 15 g fat per serving. Using standard Atwater factors, approximately how many total kilocalories does this serving provide?', '["455 kcal", "395 kcal", "275 kcal", "605 kcal"]'::jsonb, 0, 'Calculation: (60 g CHO x 4) + (20 g protein x 4) + (15 g fat x 9) = 240 + 80 + 135 = 455 kcal.', 'Mixed Revision'),
(143, 'Nutrition and Physiotherapy in Critical Care', 'Raised intracranial pressure above what value is a contraindication to physiotherapy?', '[">5mmHg", ">20mmHg", ">50mmHg", "ICP is not a consideration"]'::jsonb, 1, 'Physiotherapy manoeuvres can transiently raise ICP further, so it''s avoided once pressure is already significantly elevated.', 'Mixed Revision'),
(144, 'Nutrition and Physiotherapy in Critical Care', 'Postural drainage is contraindicated in a patient with raised ICP above:', '["ICP is not relevant to PD", "5mmHg", "20mmHg", "100mmHg"]'::jsonb, 2, 'Head-down positioning used in some PD positions can further raise ICP, which is dangerous once it''s already elevated.', 'Mixed Revision'),
(145, 'Nutrition and Physiotherapy in Critical Care', 'Percussion during airway clearance techniques is performed using:', '["Flat, open-palm slapping", "Mechanical hammers only", "Cupped hands", "A closed fist"]'::jsonb, 2, 'Cupping the hands traps a cushion of air that transmits a rhythmic vibration into the chest wall without causing direct pain from a flat strike.', 'Mixed Revision'),
(146, 'Nutrition and Physiotherapy in Critical Care', 'Enteral feeding is preferred to parenteral because it:', '["It needs no monitoring once it has started", "It is always more accurate in calorie delivery", "It avoids every risk of aspiration completely", "It maintains gut integrity with fewer infections"]'::jsonb, 3, 'TPN is reserved for when the gut cannot be used.', 'Mixed Revision'),
(147, 'Nutrition and Physiotherapy in Critical Care', 'Before giving an NG feed, the nurse confirms tube position by:', '["Asking the patient if it feels right", "Listening for injected air (whoosh test)", "Placing the tube end in a cup of water", "Aspirate pH 5.5 or below, or X-ray"]'::jsonb, 3, 'The ''whoosh'' test is unreliable.', 'Mixed Revision'),
(148, 'Nutrition and Physiotherapy in Critical Care', 'To reduce aspiration during enteral feeding, the patient should be:', '["Flat on the back", "Head-down tilt", "Prone without support", "Head elevated 30–45 degrees"]'::jsonb, 3, 'Check tolerance and gastric distension.', 'Mixed Revision'),
(149, 'Nutrition and Physiotherapy in Critical Care', 'A patient on TPN develops fever and rigors. The nurse suspects:', '["A normal reaction to the lipids", "Dehydration from the glucose load", "Refeeding syndrome from the TPN", "Catheter-related bloodstream infection"]'::jsonb, 3, 'Take cultures from line and periphery.', 'Mixed Revision'),
(150, 'Nutrition and Physiotherapy in Critical Care', 'Hyperglycaemia during TPN is managed by:', '["Ignoring glucose levels while on TPN", "Giving extra dextrose to the TPN", "Insulin and adjusting the glucose content", "Stopping all nutrition immediately"]'::jsonb, 2, 'Target glucose about 6–10 mmol/L.', 'Mixed Revision'),
(151, 'Nutrition and Physiotherapy in Critical Care', 'A burn patient''s protein requirement is:', '["Increased, about 1.5–2 g/kg/day", "Normal at 0.8 g/kg/day", "Reduced to 0.5 g/kg/day", "Nil until healing begins"]'::jsonb, 0, 'Hypermetabolism increases needs.', 'Mixed Revision'),
(152, 'Nutrition and Physiotherapy in Critical Care', 'Fat provides how many kcal per gram?', '["2", "9", "7", "4"]'::jsonb, 1, 'Carbohydrate and protein provide 4 kcal/g; alcohol 7 kcal/g.', 'Mixed Revision'),
(153, 'Nutrition and Physiotherapy in Critical Care', 'In COPD patients, excessive carbohydrate feeding can:', '["Raise CO₂ production and worsen respiratory failure", "Lower the PaCO₂ by improving ventilation", "Improve weaning by giving energy to the muscles", "Reduce the oxygen consumption of the body"]'::jsonb, 0, 'Avoid overfeeding.', 'Mixed Revision'),
(154, 'Nutrition and Physiotherapy in Critical Care', 'Chest physiotherapy aims to:', '["Replace the need for any suctioning", "Reduce the cardiac output and heart rate", "Clear secretions, re-expand lungs, aid ventilation", "Increase sedation and reduce agitation"]'::jsonb, 2, 'Techniques include positioning, percussion and breathing exercises.', 'Mixed Revision'),
(155, 'Nutrition and Physiotherapy in Critical Care', 'Suctioning should be limited to about:', '["60 seconds or more each time", "2 minutes for every pass", "As long as secretions appear", "10–15 seconds, with pre-oxygenation"]'::jsonb, 3, 'Prolonged suction causes hypoxia and arrhythmias.', 'Mixed Revision'),
(156, 'Nutrition and Physiotherapy in Critical Care', 'Suction pressure for adults is usually:', '["300–400 mmHg", "100–150 mmHg", "500 mmHg", "20–30 mmHg"]'::jsonb, 1, 'High pressures damage mucosa.', 'Mixed Revision'),
(157, 'Nutrition and Physiotherapy in Critical Care', 'Early mobilisation in ICU includes:', '["Deep sedation to reduce oxygen use", "Bed rest for all ventilated patients", "Avoiding physiotherapy until extubation", "Sitting out, standing and walking when stable"]'::jsonb, 3, 'It reduces ICU-acquired weakness and delirium.', 'Mixed Revision'),
(158, 'Nutrition and Physiotherapy in Critical Care', 'A contraindication to chest percussion is:', '["Sputum retention in the lower lobes", "Pneumonia with purulent secretions", "Rib fractures or severe osteoporosis", "Atelectasis of the left lower lobe"]'::jsonb, 2, 'Also avoid over bleeding sites.', 'Mixed Revision'),
(159, 'Nutrition and Physiotherapy in Critical Care', 'Clinical outcome measures in ICU physiotherapy include:', '["Hearing level and balance assessment", "Muscle strength, mobility level, weaning time", "Hair growth and the condition of the nails", "Visual acuity and colour vision testing"]'::jsonb, 1, 'MRC sum score and ICU mobility scale are used.', 'Mixed Revision'),
(160, 'Nutrition and Physiotherapy in Critical Care', 'Manual hyperoxygenation before suction is used to:', '["Reduce the cardiac output and heart rate", "Increase the CO₂ level in the blood", "Prevent hypoxaemia during suction", "Help to remove the endotracheal tube"]'::jsonb, 2, '100% oxygen for 30–60 seconds is common.', 'Mixed Revision'),
(161, 'ICU Management IV: Running a Safe Unit', 'The first step in planning a new ICU service is:', '["Recruiting doctors from abroad", "Painting and decorating the unit", "Needs assessment of the population", "Buying ventilators and monitors first"]'::jsonb, 2, 'Planning includes bed numbers, staffing, equipment and budget.', 'Ethics, Law & Management'),
(162, 'ICU Management IV: Running a Safe Unit', 'ICU bed numbers in a general hospital are often planned at about:', '["50% of total hospital beds", "1–4% of total hospital beds", "Less than 0.01% of beds", "25% of total hospital beds"]'::jsonb, 1, 'Tertiary centres need a higher proportion.', 'Ethics, Law & Management'),
(163, 'ICU Management IV: Running a Safe Unit', 'A clear nursing hierarchy in ICU helps by:', '["Removing accountability from leaders", "Preventing teamwork on the unit", "Defining responsibility and communication", "Increasing confusion among staff"]'::jsonb, 2, 'The charge nurse coordinates each shift.', 'Ethics, Law & Management'),
(164, 'ICU Management IV: Running a Safe Unit', 'The charge nurse on an ICU shift is responsible for:', '["Allocating patients, coordinating care, solving problems", "Prescribing drugs and fluids for all the patients", "Performing emergency surgery at the bedside", "Doing all the patient care alone without any help"]'::jsonb, 0, 'They also communicate with doctors and managers.', 'Ethics, Law & Management'),
(165, 'ICU Management IV: Running a Safe Unit', 'Supervision of ICU students and juniors aims to:', '["Replace formal teaching sessions", "Increase the workload of the juniors", "Punish errors made by students", "Ensure safe care and support learning"]'::jsonb, 3, 'Preceptors provide feedback.', 'Ethics, Law & Management'),
(166, 'ICU Management IV: Running a Safe Unit', 'Effective handover in ICU uses:', '["A structured tool such as SBAR, at the bedside", "No handover, as notes are enough", "An unstructured chat in the corridor", "Notes left on the bed for the next nurse"]'::jsonb, 0, 'Bedside handover allows checking of lines and pumps.', 'Ethics, Law & Management'),
(167, 'ICU Management IV: Running a Safe Unit', 'Leadership style that involves staff in decisions is:', '["Bureaucratic (rule-bound)", "Laissez-faire (hands-off)", "Autocratic (directive)", "Democratic (participative)"]'::jsonb, 3, 'It increases commitment but can be slow.', 'Ethics, Law & Management'),
(168, 'ICU Management IV: Running a Safe Unit', 'Laissez-faire leadership in ICU may lead to:', '["Quicker decisions in emergencies", "Poor coordination and unsafe care", "Clear accountability", "Better teamwork always"]'::jsonb, 1, 'It works only with highly skilled, motivated teams.', 'Ethics, Law & Management'),
(169, 'ICU Management IV: Running a Safe Unit', 'Authority in management means:', '["Seniority in age within the team", "Personal popularity among the staff", "The number of qualifications held", "The legitimate right to give instructions"]'::jsonb, 3, 'Authority comes with responsibility and accountability.', 'Ethics, Law & Management'),
(170, 'ICU Management IV: Running a Safe Unit', 'A policy on ICU admission and discharge criteria improves:', '["Shorter waiting times only", "Better catering services", "Longer visiting hours", "Fair and consistent use of beds"]'::jsonb, 3, 'It supports triage decisions.', 'Ethics, Law & Management'),
(171, 'ICU Management IV: Running a Safe Unit', 'Equipment failure during use in ICU should be:', '["Ignored until it breaks down completely", "Reported, labelled out of use, sent for repair", "Used carefully anyway until replaced", "Hidden in a store to avoid blame"]'::jsonb, 1, 'Incidents are reported for safety review.', 'Ethics, Law & Management'),
(172, 'ICU Management IV: Running a Safe Unit', 'A drug error audit in ICU is used to:', '["Identify and punish the nurses", "Increase the number of errors", "Reduce the reporting of errors", "Identify patterns and improve systems"]'::jsonb, 3, 'Double-checking and smart pumps reduce errors.', 'Ethics, Law & Management'),
(173, 'ICU Management IV: Running a Safe Unit', 'Communication with relatives in ICU should be:', '["Regular, honest and coordinated by the team", "Given in technical jargon to be accurate", "Done only by porters and cleaners", "Avoided to save time for clinical care"]'::jsonb, 0, 'Family meetings document discussions.', 'Ethics, Law & Management'),
(174, 'ICU Management IV: Running a Safe Unit', 'In-service training in ICU should be:', '["Random and offered only occasionally", "Given only to the medical doctors", "Given only after a serious error", "Planned around identified learning needs"]'::jsonb, 3, 'It maintains competence.', 'Ethics, Law & Management'),
(175, 'ICU Management IV: Running a Safe Unit', 'The ICU unit manager reports mainly to:', '["The catering department head", "The hospital pharmacist only", "The nursing service and hospital management", "The patients'' relatives and visitors"]'::jsonb, 2, 'Reports include activity, quality and resources.', 'Ethics, Law & Management'),
(176, 'ICU Management IV: Running a Safe Unit', 'Staff health and safety in ICU includes:', '["No precautions, as ICU staff are low risk", "Ignoring needle-stick injuries if they are small", "Unlimited overtime to cover shortages", "Vaccination, PPE, manual handling training, support"]'::jsonb, 3, 'Hepatitis B vaccination is essential.', 'Ethics, Law & Management'),
(177, 'ICU Management IV: Running a Safe Unit', 'A needle-stick injury in ICU should be:', '["Washed, reported at once, assessed for prophylaxis", "Sucked to remove the blood from the wound", "Reported at the end of the month to the manager", "Ignored if the injury is small and not bleeding"]'::jsonb, 0, 'HIV post-exposure prophylaxis is started within hours.', 'Ethics, Law & Management'),
(178, 'ICU Management IV: Running a Safe Unit', 'An ICU policy manual should be:', '["Written once and never reviewed again", "Available only to managers and seniors", "Kept locked in the manager''s office", "Up to date, accessible and known to staff"]'::jsonb, 3, 'Policies are reviewed regularly.', 'Ethics, Law & Management'),
(179, 'ICU Management IV: Running a Safe Unit', 'Teamwork in ICU is improved by:', '["Competition between staff members", "Strict silence during every shift", "Avoiding team meetings and briefings", "Clear roles, communication training, respect"]'::jsonb, 3, 'Crew resource management principles help.', 'Ethics, Law & Management'),
(180, 'ICU Management IV: Running a Safe Unit', 'The role of the nurse in ICU unit organisation includes:', '["Planning care, managing resources, keeping standards", "Only completing the nursing documentation", "Only following orders from doctors without question", "Only cleaning and tidying the unit each shift"]'::jsonb, 0, 'Nurses are central to ICU safety.', 'Ethics, Law & Management'),
(181, 'Neonatal and Paediatric Critical Care III', 'When the neonates heart rate falls or fails to respond after five inflation breath next action is', '["Commence chest compression", "Insert umbilical catheter", "Insert endotracheal tube", "Recheck airway"]'::jsonb, 0, 'If heart rate remains low after 5 inflation breaths, chest compressions should begin.', 'Obstetric & Neonatal'),
(182, 'Neonatal and Paediatric Critical Care III', 'Blue colour, Moderate tone, Inadequate breath and Slow heart rate in a neonate should be followed by which action', '["Wrap baby and handover to mother", "Commence breastfeeding", "Commence active resuscitation", "Keep baby in the cot"]'::jsonb, 2, 'Blue colour, poor tone, inadequate breathing, and slow heart rate mean the neonate needs active resuscitation.', 'Obstetric & Neonatal'),
(183, 'Neonatal and Paediatric Critical Care III', 'One of the following neonates does not need resuscitation', '["Baby whose mother is on sedatives", "Baby with hypothermia", "Baby with congenital heart disease", "Baby with heart rate of 100bpm"]'::jsonb, 3, 'A heart rate of 100bpm is within the normal newborn range and does not indicate a need for resuscitation.', 'Obstetric & Neonatal'),
(184, 'Neonatal and Paediatric Critical Care III', 'The APGAR score is assessed at:', '["Only once, at 24 hours after birth", "1 and 5 minutes after birth", "Before delivery, using the CTG", "30 minutes and 1 hour after birth"]'::jsonb, 1, 'It includes heart rate, respiration, tone, reflex irritability and colour.', 'Obstetric & Neonatal'),
(185, 'Neonatal and Paediatric Critical Care III', 'A newborn with HR 80, gasping breaths and floppy tone needs:', '["Adrenaline first", "Chest compressions immediately", "Bag-mask ventilation", "Routine care with the mother"]'::jsonb, 2, 'If HR remains below 60 after effective ventilation, start compressions.', 'Obstetric & Neonatal'),
(186, 'Neonatal and Paediatric Critical Care III', 'Thermal care of the newborn includes:', '["Bathing the baby immediately after birth", "Drying, removing wet towels, skin-to-skin or warmer", "Leaving the baby wet until the cord is cut", "Nursing the baby in a cool, airy room"]'::jsonb, 1, 'Hypothermia increases mortality.', 'Obstetric & Neonatal'),
(187, 'Neonatal and Paediatric Critical Care III', 'Phototherapy works by:', '["Blocking the liver enzymes temporarily", "Increasing the production of bilirubin", "Destroying the baby''s red cells faster", "Converting bilirubin to water-soluble isomers"]'::jsonb, 3, 'Blue light (430–490 nm) is most effective.', 'Obstetric & Neonatal'),
(188, 'Neonatal and Paediatric Critical Care III', 'Exchange transfusion is indicated when bilirubin:', '["Is within the normal range for age", "Is falling steadily on phototherapy", "Is just above the phototherapy line only", "Reaches exchange levels or shows encephalopathy"]'::jsonb, 3, 'Levels depend on age and gestation.', 'Obstetric & Neonatal'),
(189, 'Neonatal and Paediatric Critical Care III', 'A neonate with seizures should first have checked:', '["Hearing response to sound", "Visual response to light", "Hip stability on testing", "Blood glucose and calcium"]'::jsonb, 3, 'Hypoglycaemia and hypocalcaemia are common treatable causes.', 'Obstetric & Neonatal'),
(190, 'Neonatal and Paediatric Critical Care III', 'First-line drug for neonatal seizures is:', '["Valproate", "Phenytoin", "Carbamazepine", "Phenobarbital"]'::jsonb, 3, 'Loading dose 20 mg/kg IV.', 'Obstetric & Neonatal'),
(191, 'Neonatal and Paediatric Critical Care III', 'Feeding intolerance in a preterm infant may indicate:', '["Necrotising enterocolitis or sepsis", "Good bowel function and tolerance", "Overhydration from IV fluids", "Normal growth and gut maturation"]'::jsonb, 0, 'Assess the abdomen and stools.', 'Obstetric & Neonatal'),
(192, 'Neonatal and Paediatric Critical Care III', 'In neonates, fluid requirements increase with:', '["Feeding by NG tube only", "Phototherapy and radiant warmers", "A lower room temperature", "Fluid restriction orders"]'::jsonb, 1, 'Insensible losses increase.', 'Obstetric & Neonatal'),
(193, 'Neonatal and Paediatric Critical Care III', 'Fluid for a child in shock is given as:', '["50 mL/kg of 10% dextrose as a single bolus", "10–20 mL/kg isotonic bolus, reassessing each time", "Oral fluids only, by cup and spoon", "Hypotonic fluid given rapidly over 10 minutes"]'::jsonb, 1, 'Watch for fluid overload.', 'Obstetric & Neonatal'),
(194, 'Neonatal and Paediatric Critical Care III', 'Signs of raised intracranial pressure in infants include:', '["Bulging fontanelle, vomiting, sunset eyes", "Normal head growth on the chart", "Sunken fontanelle with a dry mouth", "Hyperactivity with increased hunger"]'::jsonb, 0, 'Hydrocephalus may cause rapid head growth.', 'Obstetric & Neonatal'),
(195, 'Neonatal and Paediatric Critical Care III', 'A child with a severe asthma attack not responding to salbutamol may need:', '["IV magnesium sulphate and oxygen", "Oral antibiotics and nothing else", "Strict fluid restriction for 24 hours", "Oral sedation and discharge home"]'::jsonb, 0, 'Aminophylline and ventilation may follow.', 'Obstetric & Neonatal'),
(196, 'Neonatal and Paediatric Critical Care III', 'Bronchiolitis in infants is most commonly caused by:', '["Respiratory syncytial virus (RSV)", "Streptococcus pneumoniae", "Haemophilus influenzae type b", "Candida albicans"]'::jsonb, 0, 'Treatment is supportive: oxygen, fluids and suction.', 'Obstetric & Neonatal'),
(197, 'Neonatal and Paediatric Critical Care III', 'Paediatric poisoning with iron tablets can cause:', '["No symptoms at any dose", "Hypoglycaemia only, with sweating", "Hypertension only, with headache", "GI bleeding, shock and liver failure"]'::jsonb, 3, 'Desferrioxamine is the antidote.', 'Obstetric & Neonatal'),
(198, 'Neonatal and Paediatric Critical Care III', 'Kerosene ingestion in a child mainly causes:', '["Acute liver failure", "Kidney stones", "Hypoglycaemia", "Aspiration pneumonitis"]'::jsonb, 3, 'Do not induce vomiting.', 'Obstetric & Neonatal'),
(199, 'Neonatal and Paediatric Critical Care III', 'A child with HIV and severe pneumonia should receive:', '["Oral paracetamol only, given at home", "Oral fluids only, with close observation", "Oxygen, antibiotics and high-dose cotrimoxazole", "Steroids alone, without any antibiotics"]'::jsonb, 2, 'Prednisolone is added for moderate-severe PCP.', 'Obstetric & Neonatal'),
(200, 'Neonatal and Paediatric Critical Care III', 'Meningococcal sepsis in a child presents with:', '["Slow weight gain over several months", "Fever, non-blanching purpuric rash, shock", "Painless jaundice with pale stools", "Itchy urticaria after an injection"]'::jsonb, 1, 'Give IV ceftriaxone immediately.', 'Obstetric & Neonatal');
